SELECT COUNT(*) FROM users as u, posts as p, postLinks as pl, votes as v WHERE u.Id = p.OwnerUserId AND p.Id = pl.RelatedPostId AND p.Id = v.PostId AND u.DownVotes>=0 AND p.Score>=-1 AND p.Score<=14 AND pl.CreationDate<='2014-06-25 13:05:06'::timestamp AND v.CreationDate>='2009-02-02 00:00:00'::timestamp;